using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents still use "Discriminator", so we must opt back in.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|<key>", so preserve the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws at runtime in EF Core 9. Removed below.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }  }

